export interface BowlingPin {
  id: number; // 1 to 10
  row: number; // 1 to 4
  col: number;
  initialPos: THREE.Vector3;
  pos: THREE.Vector3;
  velocity: THREE.Vector3;
  angularVelocity: THREE.Vector3;
  rot: THREE.Euler;
  isKnocked: boolean;
  isSwept: boolean;
  knockAngle: number;
  meshGroup: THREE.Group;
  bodyMesh: THREE.Mesh;
  stripe1Mesh: THREE.Mesh;
  stripe2Mesh: THREE.Mesh;
  spotMesh: THREE.Mesh;
}

export interface FrameScore {
  frameNum: number;
  roll1: number | null; // null if not rolled, 10 = Strike
  roll2: number | null; // null if not rolled, or not applicable if Strike
  roll3: number | null; // For 5th frame fill ball
  isStrike: boolean;
  isSpare: boolean;
  runningTotal: number | null;
}

export interface BowlerState {
  name: string;
  frames: FrameScore[];
  totalScore: number;
  strikesCount: number;
  sparesCount: number;
  gutterCount: number;
  currentStreak: number;
}

export type CameraViewMode = 'tee' | 'drone' | 'pocket';

