// ============================================================================
// Procedural Textures & Materials (UV Blacklight Glow)
// ============================================================================

/**
 * Creates glossy maple hardwood bowling lane texture with glowing targeting arrows
 */
function createHardwoodLaneTexture(): THREE.CanvasTexture {
  const canvas = document.createElement('canvas');
  canvas.width = 1024;
  canvas.height = 2048;
  const ctx = canvas.getContext('2d')!;

  // Deep dark wood base with blacklight tint
  ctx.fillStyle = '#181028';
  ctx.fillRect(0, 0, 1024, 2048);

  // Bowling lane maple planks
  const plankWidth = 1024 / 39; // 39 regulation lane boards
  for (let i = 0; i < 39; i++) {
    const isDark = i % 2 === 0;
    ctx.fillStyle = isDark ? '#231838' : '#2b1f44';
    ctx.fillRect(i * plankWidth, 0, plankWidth - 1, 2048);

    // Subtle grain lines
    ctx.strokeStyle = '#150c22';
    ctx.lineWidth = 1;
    ctx.strokeRect(i * plankWidth, 0, plankWidth, 2048);
  }

  // Glowing UV Neon Arrows at ~1/3 down the lane
  ctx.fillStyle = '#06b6d4';
  ctx.shadowColor = '#06b6d4';
  ctx.shadowBlur = 12;

  const arrowY = 1400;
  const arrowPositions = [0.2, 0.35, 0.5, 0.65, 0.8];
  arrowPositions.forEach((normX) => {
    const ax = normX * 1024;
    ctx.beginPath();
    ctx.moveTo(ax, arrowY - 60);
    ctx.lineTo(ax + 24, arrowY + 40);
    ctx.lineTo(ax, arrowY + 15);
    ctx.lineTo(ax - 24, arrowY + 40);
    ctx.closePath();
    ctx.fill();
  });

  // Glowing Foul Line at bottom
  ctx.fillStyle = '#ec4899';
  ctx.shadowColor = '#ec4899';
  ctx.shadowBlur = 18;
  ctx.fillRect(0, 1980, 1024, 24);

  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(1, 2);
  return tex;
}

/**
 * Creates retro neon arch sign texture
 */
function createCosmicArchTexture(): THREE.CanvasTexture {
  const canvas = document.createElement('canvas');
  canvas.width = 1024;
  canvas.height = 256;
  const ctx = canvas.getContext('2d')!;

  ctx.fillStyle = '#0a0618';
  ctx.fillRect(0, 0, 1024, 256);

  ctx.strokeStyle = '#ec4899';
  ctx.lineWidth = 10;
  ctx.strokeRect(12, 12, 1000, 232);

  ctx.fillStyle = '#ffffff';
  ctx.font = '900 68px -apple-system, sans-serif';
  ctx.textAlign = 'center';
  ctx.shadowColor = '#06b6d4';
  ctx.shadowBlur = 24;
  ctx.fillText('★ COSMIC BOWLING ★', 512, 120);

  ctx.fillStyle = '#facc15';
  ctx.font = '700 32px -apple-system, sans-serif';
  ctx.shadowColor = '#ec4899';
  ctx.shadowBlur = 16;
  ctx.fillText('UV BLACKLIGHT ARCADE LANES', 512, 185);

  const tex = new THREE.CanvasTexture(canvas);
  return tex;
}

// ============================================================================
// Web Audio Procedural Synthesizer
// ============================================================================

function initAudio() {
  if (!bowlCtx.audioCtx) {
    const AudioContextClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    bowlCtx.audioCtx = new AudioContextClass();
  }
  if (bowlCtx.audioCtx && bowlCtx.audioCtx.state === 'suspended') {
    bowlCtx.audioCtx.resume();
  }
}

/**
 * Procedural bowling audio effects
 */
function playAudio(type: 'strike' | 'spare' | 'pin_hit' | 'pin_clatter' | 'gutter' | 'sweep' | 'wood_roll') {
  if (bowlCtx.audioMuted) return;
  initAudio();
  if (!bowlCtx.audioCtx) return;

  const ac = bowlCtx.audioCtx;
  const now = ac.currentTime;

  switch (type) {
    case 'pin_hit': {
      // Solid resonant wooden pin impact
      const osc = ac.createOscillator();
      const gain = ac.createGain();
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(260 + Math.random() * 80, now);
      osc.frequency.exponentialRampToValueAtTime(60, now + 0.22);
      gain.gain.setValueAtTime(0.9, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.22);
      osc.connect(gain);
      gain.connect(ac.destination);
      osc.start(now);
      osc.stop(now + 0.22);

      // Noise clatter burst
      const bufSize = Math.floor(ac.sampleRate * 0.12);
      const buffer = ac.createBuffer(1, bufSize, ac.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufSize; i++) {
        data[i] = (Math.random() * 2 - 1) * Math.exp(-i / (ac.sampleRate * 0.03));
      }
      const noise = ac.createBufferSource();
      const noiseGain = ac.createGain();
      noise.buffer = buffer;
      noiseGain.gain.setValueAtTime(0.6, now);
      noiseGain.gain.exponentialRampToValueAtTime(0.01, now + 0.12);
      noise.connect(noiseGain);
      noiseGain.connect(ac.destination);
      noise.start(now);
      break;
    }

    case 'pin_clatter': {
      // Secondary pin-to-pin cascade clatter
      const clatterPitches = [340, 420, 280, 510];
      clatterPitches.forEach((p, idx) => {
        const osc = ac.createOscillator();
        const gain = ac.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(p + (Math.random() * 40 - 20), now + idx * 0.04);
        gain.gain.setValueAtTime(0.35, now + idx * 0.04);
        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.18 + idx * 0.04);
        osc.connect(gain);
        gain.connect(ac.destination);
        osc.start(now + idx * 0.04);
        osc.stop(now + 0.18 + idx * 0.04);
      });
      break;
    }

    case 'strike': {
      // 90s Synth Arpeggio Victory Chimes (C major 7th flourish)
      const notes = [261.63, 329.63, 392.00, 523.25, 659.25, 783.99, 1046.50];
      notes.forEach((freq, idx) => {
        const osc = ac.createOscillator();
        const gain = ac.createGain();
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(freq, now + idx * 0.07);
        gain.gain.setValueAtTime(0.35, now + idx * 0.07);
        gain.gain.exponentialRampToValueAtTime(0.005, now + 0.6 + idx * 0.07);
        osc.connect(gain);
        gain.connect(ac.destination);
        osc.start(now + idx * 0.07);
        osc.stop(now + 0.6 + idx * 0.07);
      });
      break;
    }

    case 'spare': {
      // 3-note ascending victory chime
      [392.00, 523.25, 783.99].forEach((freq, idx) => {
        const osc = ac.createOscillator();
        const gain = ac.createGain();
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(freq, now + idx * 0.1);
        gain.gain.setValueAtTime(0.4, now + idx * 0.1);
        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.5 + idx * 0.1);
        osc.connect(gain);
        gain.connect(ac.destination);
        osc.start(now + idx * 0.1);
        osc.stop(now + 0.5 + idx * 0.1);
      });
      break;
    }

    case 'gutter': {
      // Dull gutter drop clunk + comedic low wah
      const osc = ac.createOscillator();
      const gain = ac.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(140, now);
      osc.frequency.exponentialRampToValueAtTime(55, now + 0.5);
      gain.gain.setValueAtTime(0.6, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.5);
      osc.connect(gain);
      gain.connect(ac.destination);
      osc.start(now);
      osc.stop(now + 0.5);
      break;
    }

    case 'sweep': {
      // Mechanical motor hum
      const osc = ac.createOscillator();
      const gain = ac.createGain();
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(110, now);
      osc.frequency.linearRampToValueAtTime(130, now + 0.4);
      gain.gain.setValueAtTime(0.25, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.8);
      osc.connect(gain);
      gain.connect(ac.destination);
      osc.start(now);
      osc.stop(now + 0.8);
      break;
    }

    case 'wood_roll': {
      // Low rumble of ball on hardwood
      const osc = ac.createOscillator();
      const gain = ac.createGain();
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(65, now);
      gain.gain.setValueAtTime(0.3, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.6);
      osc.connect(gain);
      gain.connect(ac.destination);
      osc.start(now);
      osc.stop(now + 0.6);
      break;
    }
  }
}

// ============================================================================
// 3D Geometry: Authentic Bowling Pin & Cosmic Alley Builders
// ============================================================================

/**
 * Builds authentic 3D bowling pin using LatheGeometry with neck stripe meshes
 */
function createBowlingPinMesh(): { group: THREE.Group; body: THREE.Mesh; s1: THREE.Mesh; s2: THREE.Mesh } {
  const group = new THREE.Group();

  // Authentic Bowling Pin Lathe Curve (height scaled to PIN_HEIGHT)
  const h = PIN_HEIGHT;
  const points: THREE.Vector2[] = [
    new THREE.Vector2(0.0, 0.0),
    new THREE.Vector2(0.24, 0.0),
    new THREE.Vector2(0.28, 0.08 * h),
    new THREE.Vector2(0.40, 0.28 * h), // Wide belly
    new THREE.Vector2(0.42, 0.38 * h),
    new THREE.Vector2(0.30, 0.55 * h),
    new THREE.Vector2(0.18, 0.70 * h), // Narrow neck
    new THREE.Vector2(0.19, 0.76 * h),
    new THREE.Vector2(0.22, 0.85 * h), // Head bulb
    new THREE.Vector2(0.21, 0.94 * h),
    new THREE.Vector2(0.10, 0.99 * h),
    new THREE.Vector2(0.0, 1.0 * h),
  ];

  const pinGeo = new THREE.LatheGeometry(points, 24);

  // High-gloss UV White Material (fluoresces under blacklight)
  const pinMat = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.15,
    metalness: 0.1,
    emissive: 0x93c5fd,
    emissiveIntensity: 0.25,
  });

  const bodyMesh = new THREE.Mesh(pinGeo, pinMat);
  bodyMesh.castShadow = true;
  bodyMesh.receiveShadow = true;
  group.add(bodyMesh);

  // Red Neck Stripes
  const stripeMat = new THREE.MeshBasicMaterial({ color: 0xef4444 });

  const s1Geo = new THREE.CylinderGeometry(0.19, 0.19, 0.05 * h, 24, 1, true);
  const s1Mesh = new THREE.Mesh(s1Geo, stripeMat);
  s1Mesh.position.y = 0.72 * h;
  group.add(s1Mesh);

  const s2Geo = new THREE.CylinderGeometry(0.195, 0.195, 0.05 * h, 24, 1, true);
  const s2Mesh = new THREE.Mesh(s2Geo, stripeMat);
  s2Mesh.position.y = 0.78 * h;
  group.add(s2Mesh);

  return { group, body: bodyMesh, s1: s1Mesh, s2: s2Mesh };
}

/**
 * Builds the Cosmic Bowling Arena, Lane, Gutters, Neon Arch, and Pinsetter
 */
function createBowlingArena() {
  const scene = bowlCtx.scene;

  // 1. Surrounding Dark Ground / Fairway
  const groundGeo = new THREE.PlaneGeometry(160, 200);
  const groundMat = new THREE.MeshStandardMaterial({
    color: 0x070514,
    roughness: 0.9,
    metalness: 0.1,
  });
  const ground = new THREE.Mesh(groundGeo, groundMat);
  ground.rotation.x = -Math.PI / 2;
  ground.position.set(0, -0.05, TARGET_DISTANCE_METERS / 2);
  ground.receiveShadow = true;
  scene.add(ground);
  bowlCtx.groundMesh = ground;

  // 2. Elevated Hardwood Bowling Lane (Z: -2m to 66m)
  const laneGeo = new THREE.BoxGeometry(LANE_WIDTH - GUTTER_WIDTH * 2, 0.25, LANE_LENGTH);
  const laneTex = createHardwoodLaneTexture();
  const laneMat = new THREE.MeshStandardMaterial({
    map: laneTex,
    roughness: 0.12,
    metalness: 0.35,
    emissive: 0x1e1035,
    emissiveIntensity: 0.4,
  });
  const lane = new THREE.Mesh(laneGeo, laneMat);
  lane.position.set(0, 0.12, TARGET_DISTANCE_METERS / 2);
  lane.receiveShadow = true;
  scene.add(lane);
  bowlCtx.laneMesh = lane;

  // 3. Neon Gutters (Left & Right Troughs)
  const gutterGeo = new THREE.BoxGeometry(GUTTER_WIDTH, 0.12, LANE_LENGTH);
  const gutterMat = new THREE.MeshStandardMaterial({
    color: 0x110e20,
    roughness: 0.4,
    metalness: 0.7,
  });

  const neonTubeMatCyan = new THREE.MeshBasicMaterial({ color: 0x06b6d4 });
  const neonTubeMatMagenta = new THREE.MeshBasicMaterial({ color: 0xec4899 });
  const tubeGeo = new THREE.CylinderGeometry(0.04, 0.04, LANE_LENGTH, 12);
  tubeGeo.rotateX(Math.PI / 2);

  [-1, 1].forEach((side) => {
    const gx = side * ((LANE_WIDTH - GUTTER_WIDTH) / 2);
    const gutter = new THREE.Mesh(gutterGeo, gutterMat);
    gutter.position.set(gx, 0.06, TARGET_DISTANCE_METERS / 2);
    gutter.receiveShadow = true;
    scene.add(gutter);

    // Glowing Neon Tube running the full length of each gutter
    const tube = new THREE.Mesh(tubeGeo, side === -1 ? neonTubeMatCyan : neonTubeMatMagenta);
    tube.position.set(gx, 0.14, TARGET_DISTANCE_METERS / 2);
    scene.add(tube);
  });

  // 4. Pin Deck (Elevated staging platform at the end of the lane)
  const pinDeckGeo = new THREE.BoxGeometry(LANE_WIDTH + 1.2, 0.3, 8.0);
  const pinDeckMat = new THREE.MeshStandardMaterial({
    color: 0x1a1230,
    roughness: 0.2,
    metalness: 0.6,
  });
  const pinDeck = new THREE.Mesh(pinDeckGeo, pinDeckMat);
  pinDeck.position.set(0, 0.14, TARGET_DISTANCE_METERS + 1.0);
  scene.add(pinDeck);

  // 5. Back Pit & Backboard Cushion
  const pitGeo = new THREE.BoxGeometry(LANE_WIDTH + 1.2, 3.5, 1.4);
  const pitMat = new THREE.MeshStandardMaterial({
    color: 0x0b0716,
    roughness: 0.8,
  });
  const pit = new THREE.Mesh(pitGeo, pitMat);
  pit.position.set(0, 1.75, TARGET_DISTANCE_METERS + 5.2);
  scene.add(pit);

  // 6. Retro Overhead Neon Arch Sign ("COSMIC BOWLING")
  const archGroup = new THREE.Group();
  archGroup.position.set(0, 0, TARGET_DISTANCE_METERS + 4.8);

  // Dual support pillars
  const pillarGeo = new THREE.CylinderGeometry(0.2, 0.25, 7.5, 16);
  const pillarMat = new THREE.MeshStandardMaterial({ color: 0x241840, metalness: 0.8, roughness: 0.2 });
  [-3.4, 3.4].forEach((px) => {
    const pillar = new THREE.Mesh(pillarGeo, pillarMat);
    pillar.position.set(px, 3.75, 0);
    archGroup.add(pillar);
  });

  // Signboard Mesh
  const signGeo = new THREE.BoxGeometry(7.2, 2.0, 0.3);
  const signTex = createCosmicArchTexture();
  const signMat = new THREE.MeshStandardMaterial({
    map: signTex,
    emissiveMap: signTex,
    emissive: 0xffffff,
    emissiveIntensity: 1.2,
    roughness: 0.3,
  });
  const sign = new THREE.Mesh(signGeo, signMat);
  sign.position.set(0, 6.5, 0);
  archGroup.add(sign);
  scene.add(archGroup);

  // 7. Pinsetter Sweep Bar
  const sweepBarGeo = new THREE.BoxGeometry(LANE_WIDTH, 0.25, 0.25);
  const sweepBarMat = new THREE.MeshStandardMaterial({
    color: 0xec4899,
    emissive: 0xec4899,
    emissiveIntensity: 0.8,
  });
  const sweepBar = new THREE.Mesh(sweepBarGeo, sweepBarMat);
  sweepBar.position.set(0, 0.35, 0);
  bowlCtx.sweepBarGroup.add(sweepBar);
  bowlCtx.sweepBarGroup.position.set(0, 0, TARGET_DISTANCE_METERS - 2.0);
  scene.add(bowlCtx.sweepBarGroup);

  // 8. 10 Giant Bowling Pins Setup
  setupPins();

  // 9. Cosmic Sky Dome & Volumetric Light Beams
  bowlCtx.atmosphere = createStadiumAtmosphere(scene, 500);

  // Volumetric searchlights angled toward the pin deck
  [-12, 12].forEach((x) => {
    const beam = createVolumetricLightBeam(26, 0.15, 12.0, 0xa855f7);
    beam.position.set(x, 18, TARGET_DISTANCE_METERS - 14);
    beam.lookAt(0, 1.2, TARGET_DISTANCE_METERS);
    scene.add(beam);
    bowlCtx.volumetricBeams.push(beam);
  });
}

/**
 * Initializes and arranges the 10 Bowling Pins into regulation triangle formation
 */
function setupPins() {
  const scene = bowlCtx.scene;
  bowlCtx.pins = [];

  // Pin triangle arrangement:
  // Row 1: Pin 1 (Headpin)
  // Row 2: Pin 2 (L), Pin 3 (R)
  // Row 3: Pin 4 (L), Pin 5 (C), Pin 6 (R)
  // Row 4: Pin 7 (LL), Pin 8 (L), Pin 9 (R), Pin 10 (RR)
  const pinLayout = [
    { id: 1, row: 1, col: 0, x: 0, z: 0 },
    { id: 2, row: 2, col: -1, x: -PIN_SPACING_X * 0.5, z: PIN_SPACING_Z },
    { id: 3, row: 2, col: 1, x: PIN_SPACING_X * 0.5, z: PIN_SPACING_Z },
    { id: 4, row: 3, col: -2, x: -PIN_SPACING_X, z: PIN_SPACING_Z * 2 },
    { id: 5, row: 3, col: 0, x: 0, z: PIN_SPACING_Z * 2 },
    { id: 6, row: 3, col: 2, x: PIN_SPACING_X, z: PIN_SPACING_Z * 2 },
    { id: 7, row: 4, col: -3, x: -PIN_SPACING_X * 1.5, z: PIN_SPACING_Z * 3 },
    { id: 8, row: 4, col: -1, x: -PIN_SPACING_X * 0.5, z: PIN_SPACING_Z * 3 },
    { id: 9, row: 4, col: 1, x: PIN_SPACING_X * 0.5, z: PIN_SPACING_Z * 3 },
    { id: 10, row: 4, col: 3, x: PIN_SPACING_X * 1.5, z: PIN_SPACING_Z * 3 },
  ];

  const spotGeo = new THREE.CircleGeometry(0.28, 24);
  spotGeo.rotateX(-Math.PI / 2);
  const spotMat = new THREE.MeshBasicMaterial({ color: 0x06b6d4 });

  pinLayout.forEach((p) => {
    const pinData = createBowlingPinMesh();
    const group = pinData.group;

    const targetX = p.x;
    const targetY = 0.25; // Sits on elevated hardwood lane deck
    const targetZ = TARGET_DISTANCE_METERS + p.z;
    const worldPos = new THREE.Vector3(targetX, targetY, targetZ);

    group.position.copy(worldPos);
    scene.add(group);

    // Glowing spot marker circle on the lane floor
    const spotMesh = new THREE.Mesh(spotGeo, spotMat);
    spotMesh.position.set(targetX, targetY + 0.01, targetZ);
    scene.add(spotMesh);

    bowlCtx.pins.push({
      id: p.id,
      row: p.row,
      col: p.col,
      initialPos: worldPos.clone(),
      pos: worldPos.clone(),
      velocity: new THREE.Vector3(0, 0, 0),
      angularVelocity: new THREE.Vector3(0, 0, 0),
      rot: new THREE.Euler(0, 0, 0),
      isKnocked: false,
      isSwept: false,
      knockAngle: 0,
      meshGroup: group,
      bodyMesh: pinData.body,
      stripe1Mesh: pinData.s1,
      stripe2Mesh: pinData.s2,
      spotMesh,
    });
  });
}

// ============================================================================
// Bowling Score Calculation Engine
// ============================================================================

function initScorecard() {
  bowlCtx.bowler.frames = [];
  for (let i = 1; i <= 5; i++) {
    bowlCtx.bowler.frames.push({
      frameNum: i,
      roll1: null,
      roll2: null,
      roll3: null,
      isStrike: false,
      isSpare: false,
      runningTotal: null,
    });
  }
  bowlCtx.currentFrame = 1;
  bowlCtx.currentBall = 1;
  bowlCtx.bowler.totalScore = 0;
  bowlCtx.bowler.strikesCount = 0;
  bowlCtx.bowler.sparesCount = 0;
  bowlCtx.bowler.gutterCount = 0;
  bowlCtx.bowler.currentStreak = 0;
  bowlCtx.isGameOver = false;
  updateScoreboardUI();
}

/**
 * Standard official bowling score calculation across 5 frames
 */
function recalculateScores() {
  const frames = bowlCtx.bowler.frames;
  let runningTotal = 0;

  for (let i = 0; i < 5; i++) {
    const f = frames[i];
    if (f.roll1 === null) break;

    if (i < 4) {
      // Standard Frames 1 to 4
      if (f.isStrike) {
        // Strike: 10 + next 2 rolls
        const nextRolls = getNextRolls(i, 2);
        if (nextRolls.length === 2) {
          runningTotal += 10 + nextRolls[0] + nextRolls[1];
          f.runningTotal = runningTotal;
        } else {
          f.runningTotal = null; // Waiting for future rolls
        }
      } else if (f.isSpare) {
        // Spare: 10 + next 1 roll
        const nextRolls = getNextRolls(i, 1);
        if (nextRolls.length === 1) {
          runningTotal += 10 + nextRolls[0];
          f.runningTotal = runningTotal;
        } else {
          f.runningTotal = null;
        }
      } else if (f.roll2 !== null) {
        // Open frame
        runningTotal += (f.roll1 || 0) + (f.roll2 || 0);
        f.runningTotal = runningTotal;
      }
    } else {
      // Final Frame 5: Sum of all completed balls
      let f5Sum = f.roll1 || 0;
      if (f.roll2 !== null) f5Sum += f.roll2;
      if (f.roll3 !== null) f5Sum += f.roll3;

      const needsBall3 = f.isStrike || f.isSpare;
      if (needsBall3) {
        if (f.roll3 !== null) {
          runningTotal += f5Sum;
          f.runningTotal = runningTotal;
        }
      } else if (f.roll2 !== null) {
        runningTotal += f5Sum;
        f.runningTotal = runningTotal;
      }
    }
  }

  // Update overall active player total
  let highestCalculated = 0;
  frames.forEach((f) => {
    if (f.runningTotal !== null) highestCalculated = f.runningTotal;
  });
  bowlCtx.bowler.totalScore = highestCalculated;
}

function getNextRolls(fromFrameIdx: number, count: number): number[] {
  const rolls: number[] = [];
  const frames = bowlCtx.bowler.frames;

  for (let i = fromFrameIdx + 1; i < frames.length; i++) {
    const f = frames[i];
    if (f.roll1 !== null) {
      rolls.push(f.roll1);
      if (rolls.length === count) return rolls;
    }
    if (f.roll2 !== null) {
      rolls.push(f.roll2);
      if (rolls.length === count) return rolls;
    }
    if (f.roll3 !== null) {
      rolls.push(f.roll3);
      if (rolls.length === count) return rolls;
    }
  }
  return rolls;
}

// ============================================================================
// Turn Flow & Pinsetter Lifecycle
// ============================================================================

/**
 * Sweeps knocked-down pins or resets fresh rack of 10 pins
 */
async function runPinsetter(isFullRackReset: boolean) {
  bowlCtx.isSweeping = true;
  showPinsetterBanner(isFullRackReset ? 'RESETTING 10 FRESH PINS...' : 'SWEEPING KNOCKED PINS...');
  playAudio('sweep');

  // 1. Lower sweep bar and animate forward
  const sweepBar = bowlCtx.sweepBarGroup;
  sweepBar.position.z = TARGET_DISTANCE_METERS - 2.0;

  const sweepStartTime = performance.now();
  const sweepDuration = 1200; // 1.2s sweep

  await new Promise<void>((resolve) => {
    const step = (time: number) => {
      const elapsed = time - sweepStartTime;
      const t = Math.min(1.0, elapsed / sweepDuration);

      // Sweep bar traverses across the pin deck
      sweepBar.position.z = (TARGET_DISTANCE_METERS - 2.0) + t * 7.5;

      if (t < 1.0) {
        requestAnimationFrame(step);
      } else {
        resolve();
      }
    };
    requestAnimationFrame(step);
  });

  // 2. Hide or restore pin meshes
  if (isFullRackReset) {
    // Reset all 10 pins upright
    bowlCtx.pins.forEach((pin) => {
      pin.isKnocked = false;
      pin.isSwept = false;
      pin.pos.copy(pin.initialPos);
      pin.meshGroup.position.copy(pin.initialPos);
      pin.meshGroup.rotation.set(0, 0, 0);
      pin.velocity.set(0, 0, 0);
      pin.angularVelocity.set(0, 0, 0);
      pin.knockAngle = 0;
      pin.meshGroup.visible = true;
    });
  } else {
    // Only sweep knocked pins off the deck
    bowlCtx.pins.forEach((pin) => {
      if (pin.isKnocked) {
        pin.isSwept = true;
        pin.meshGroup.visible = false;
      }
    });
  }

  // 3. Return sweep bar to home position
  sweepBar.position.z = TARGET_DISTANCE_METERS - 2.0;
  bowlCtx.isSweeping = false;
  hidePinsetterBanner();
  updateRadarUI();
}

/**
 * Resolves the shot results, updates frame score, and triggers animations
 */
async function resolveShotCompletion(pinsHitCount: number) {
  bowlCtx.isTurnResolving = true;
  const fIdx = bowlCtx.currentFrame - 1;
  const f = bowlCtx.bowler.frames[fIdx];
  const ballNum = bowlCtx.currentBall;

  let isStrike = false;
  let isSpare = false;

  if (bowlCtx.currentFrame < 5) {
    // Frames 1 - 4
    if (ballNum === 1) {
      f.roll1 = pinsHitCount;
      if (pinsHitCount === 10) {
        isStrike = true;
        f.isStrike = true;
        bowlCtx.bowler.strikesCount++;
        bowlCtx.bowler.currentStreak++;
      } else {
        bowlCtx.bowler.currentStreak = 0;
      }

      if (pinsHitCount === 0) {
        bowlCtx.bowler.gutterCount++;
        triggerRetroOverlay('gutter');
        playAudio('gutter');
      } else if (isStrike) {
        triggerRetroOverlay(bowlCtx.bowler.currentStreak >= 3 ? 'turkey' : 'strike');
        playAudio('strike');
        if (bowlCtx.particles) {
          bowlCtx.particles.spawnCelebrationFireworks(new THREE.Vector3(0, 3, TARGET_DISTANCE_METERS), 'gold', 140);
        }
      }
    } else {
      // Ball 2
      f.roll2 = pinsHitCount;
      const prevPins = f.roll1 || 0;
      if (prevPins + pinsHitCount === 10) {
        isSpare = true;
        f.isSpare = true;
        bowlCtx.bowler.sparesCount++;
        triggerRetroOverlay('spare');
        playAudio('spare');
      } else if (pinsHitCount === 0) {
        playAudio('gutter');
      }
    }
  } else {
    // Final Frame 5 Logic
    if (ballNum === 1) {
      f.roll1 = pinsHitCount;
      if (pinsHitCount === 10) {
        isStrike = true;
        f.isStrike = true;
        bowlCtx.bowler.strikesCount++;
        triggerRetroOverlay('strike');
        playAudio('strike');
      }
    } else if (ballNum === 2) {
      f.roll2 = pinsHitCount;
      if (!f.isStrike && (f.roll1 || 0) + pinsHitCount === 10) {
        isSpare = true;
        f.isSpare = true;
        bowlCtx.bowler.sparesCount++;
        triggerRetroOverlay('spare');
        playAudio('spare');
      } else if (f.isStrike && pinsHitCount === 10) {
        triggerRetroOverlay('strike');
        playAudio('strike');
      }
    } else if (ballNum === 3) {
      f.roll3 = pinsHitCount;
      if (pinsHitCount === 10) {
        triggerRetroOverlay('strike');
        playAudio('strike');
      }
    }
  }

  recalculateScores();
  updateScoreboardUI();

  // Pinsetter Sweep & Next Turn Advance
  const isFrame5 = bowlCtx.currentFrame === 5;
  const isStrikeOrSpare = isStrike || isSpare;

  if (isFrame5) {
    // 5th Frame turn progression
    if (ballNum === 1) {
      if (isStrike) {
        await runPinsetter(true);
        bowlCtx.currentBall = 2;
      } else {
        await runPinsetter(false);
        bowlCtx.currentBall = 2;
      }
    } else if (ballNum === 2) {
      if (f.isStrike || f.isSpare) {
        await runPinsetter(true);
        bowlCtx.currentBall = 3;
      } else {
        // Game Over!
        endGame();
        return;
      }
    } else {
      // Ball 3 complete -> Game Over!
      endGame();
      return;
    }
  } else {
    // Standard Frames 1 - 4
    if (isStrike) {
      await runPinsetter(true);
      bowlCtx.currentFrame++;
      bowlCtx.currentBall = 1;
    } else if (ballNum === 1) {
      await runPinsetter(false);
      bowlCtx.currentBall = 2;
    } else {
      // Ball 2 complete -> Next Frame
      await runPinsetter(true);
      bowlCtx.currentFrame++;
      bowlCtx.currentBall = 1;
    }
  }

  bowlCtx.isTurnResolving = false;
  updateScoreboardUI();
}

function endGame() {
  bowlCtx.isGameOver = true;
  showRecapModal();
}

// ============================================================================
// Shot Execution & Ball-to-Pin Collision Physics
// ============================================================================

export function processShotImpact(shot: OpenGolfSim.Shot) {
  if (bowlCtx.isTurnResolving || bowlCtx.isGameOver) return;

  const speed = Number(shot.ballSpeed) || 85;
  const vla = Number(shot.verticalLaunchAngle) || 28;
  const hla = Number(shot.horizontalLaunchAngle) || 0;

  updateTelemetryUI(speed, vla, hla);
  bowlCtx.pinsKnockedThisShot = 0;

  // 1. Launch Golf Ball into 3D World
  if (bowlCtx.golfBall) {
    const fullShot: OpenGolfSim.Shot = {
      ballSpeed: speed,
      verticalLaunchAngle: vla,
      horizontalLaunchAngle: hla,
      spinSpeed: Number(shot.spinSpeed) || Number(shot.totalSpin) || 5400,
      spinAxis: Number(shot.spinAxis) || 0,
      totalSpin: Number(shot.totalSpin) || 5400,
    };
    bowlCtx.golfBall.launchShot(fullShot);
    playAudio('wood_roll');

    if (bowlCtx.camera && bowlCtx.viewMode === 'tee') {
      bowlCtx.camera.setTracking(true, 0.8);
    }
  }

  // 2. Physical Collision Simulation against standing pins
  simulatePinCollisions(speed, hla);
}

/**
 * Simulates ball impact trajectory against standing pins and triggers domino chain reactions
 */
function simulatePinCollisions(ballSpeedMph: number, hlaDeg: number) {
  // Lateral entry point at pin deck: hla determines entry offset
  // Center (0 deg) hits 1-pin directly. Slight +1.2 deg hits 1-3 pocket (Strike!)
  const entryX = (hlaDeg * 0.45);
  const isGutter = Math.abs(entryX) > (LANE_WIDTH / 2 - 0.2);

  if (isGutter) {
    // Errant shot dropped directly into the gutter
    setTimeout(() => {
      showToast('GUTTER BALL!', 'Shot dropped into the gutter trough', '0 PINS');
      resolveShotCompletion(0);
    }, 1800);
    return;
  }

  // Calculate ball arrival time (~1.2s to 1.8s based on speed)
  const impactDelayMs = Math.max(900, Math.min(2200, (65.0 / (ballSpeedMph * 0.447)) * 500));

  setTimeout(() => {
    let pinsKnockedNow = 0;
    const standingPins = bowlCtx.pins.filter((p) => !p.isKnocked && !p.isSwept);

    standingPins.forEach((pin) => {
      // Distance from ball entry line to pin
      const dx = pin.pos.x - entryX;
      const dz = pin.pos.z - TARGET_DISTANCE_METERS;

      // Realistic bowling pocket physics:
      // Pocket hits (+0.4m to +0.8m) cause massive cascading domino strikes!
      let hitProbability = 0;

      if (Math.abs(entryX - 0.4) < 0.35) {
        // Pocket Strike (1-3 pocket)
        hitProbability = 0.98;
      } else if (Math.abs(entryX + 0.4) < 0.35) {
        // Brooklyn Strike (1-2 pocket)
        hitProbability = 0.92;
      } else if (Math.abs(dx) < 0.9) {
        // Direct or near-direct hit on this pin row
        hitProbability = Math.max(0, 1.0 - Math.abs(dx) / 1.1);
      } else if (Math.abs(entryX) > 1.4 && (pin.id === 7 || pin.id === 10)) {
        // Corner pin pickups
        hitProbability = Math.abs(pin.pos.x - entryX) < 0.8 ? 0.85 : 0.1;
      }

      if (Math.random() < hitProbability) {
        knockPinDown(pin, ballSpeedMph, entryX);
        pinsKnockedNow++;
      }
    });

    bowlCtx.pinsKnockedThisShot = pinsKnockedNow;
    bowlCtx.cameraTrauma = Math.min(1.0, pinsKnockedNow * 0.15);

    if (pinsKnockedNow > 0) {
      playAudio('pin_hit');
      setTimeout(() => playAudio('pin_clatter'), 120);

      const toastTitle = pinsKnockedNow === 10
        ? '💥 STRIKE! PERFECT POCKET!'
        : pinsKnockedNow >= 7
        ? '🎳 HEAVY HIT!'
        : '✨ SOLID CONTACT';

      showToast(toastTitle, `${pinsKnockedNow} Pins Knocked Down!`, `+${pinsKnockedNow} PINS`);
    } else {
      showToast('CLEAN MISS!', 'Ball passed between standing pins', '0 PINS');
    }

    // Advance turn after pins settle
    setTimeout(() => {
      resolveShotCompletion(pinsKnockedNow);
    }, 1800);
  }, impactDelayMs);
}

/**
 * Physically tumbles a bowling pin with kinetic impulse
 */
function knockPinDown(pin: BowlingPin, ballSpeedMph: number, entryX: number) {
  if (pin.isKnocked) return;
  pin.isKnocked = true;

  // Kinetic impulse vector away from ball entry
  const impulseDir = new THREE.Vector3(
    pin.pos.x - entryX + (Math.random() - 0.5) * 0.4,
    0.8 + Math.random() * 0.4,
    1.2 + Math.random() * 0.8
  ).normalize();

  const impulseSpeed = (ballSpeedMph / 85.0) * (3.5 + Math.random() * 2.5);
  pin.velocity.copy(impulseDir).multiplyScalar(impulseSpeed);

  // Angular tumble torque
  pin.angularVelocity.set(
    (Math.random() - 0.5) * 8.0,
    (Math.random() - 0.5) * 6.0,
    (Math.random() - 0.5) * 8.0
  );

  updateRadarUI();
}

// ============================================================================
// UI Updates & 90s CRT Retro Animations
// ============================================================================

function updateScoreboardUI() {
  const frames = bowlCtx.bowler.frames;
  const currentF = bowlCtx.currentFrame;

  // Update Frame status badges
  const frameBadge = document.getElementById('frame-status-badge');
  if (frameBadge) {
    frameBadge.textContent = bowlCtx.isGameOver
      ? 'GAME FINISHED'
      : `FRAME ${currentF} • BALL ${bowlCtx.currentBall}`;
  }

  const hudTotal = document.getElementById('hud-total-score');
  if (hudTotal) {
    hudTotal.textContent = `${bowlCtx.bowler.totalScore}`;
  }

  const streakText = document.getElementById('streak-text');
  if (streakText) {
    const s = bowlCtx.bowler.currentStreak;
    streakText.textContent = s >= 3 ? `TURKEY! (${s}X STRIKES)` : s > 0 ? `${s}X STRIKE STREAK` : 'NO STREAK';
  }

  // Populate 5 Frame cells
  for (let i = 1; i <= 5; i++) {
    const f = frames[i - 1];
    const cellEl = document.getElementById(`frame-cell-${i}`);
    if (!cellEl) continue;

    if (i === currentF && !bowlCtx.isGameOver) {
      cellEl.classList.add('active');
    } else {
      cellEl.classList.remove('active');
    }

    const r1El = document.getElementById(`f${i}-r1`);
    const r2El = document.getElementById(`f${i}-r2`);
    const totalEl = document.getElementById(`f${i}-total`);

    if (r1El) {
      if (f.isStrike) {
        r1El.textContent = 'X';
        r1El.className = 'roll-box strike';
      } else if (f.roll1 !== null) {
        r1El.textContent = f.roll1 === 0 ? '-' : `${f.roll1}`;
        r1El.className = 'roll-box';
      } else {
        r1El.textContent = '-';
        r1El.className = 'roll-box';
      }
    }

    if (r2El) {
      if (f.isSpare) {
        r2El.textContent = '/';
        r2El.className = 'roll-box spare';
      } else if (f.roll2 !== null) {
        r2El.textContent = f.roll2 === 0 ? '-' : `${f.roll2}`;
        r2El.className = 'roll-box';
      } else {
        r2El.textContent = '-';
        r2El.className = 'roll-box';
      }
    }

    // 5th Frame 3rd roll box
    if (i === 5) {
      const r3El = document.getElementById('f5-r3');
      if (r3El) {
        if (f.roll3 !== null) {
          r3El.textContent = f.roll3 === 10 ? 'X' : f.roll3 === 0 ? '-' : `${f.roll3}`;
          r3El.className = f.roll3 === 10 ? 'roll-box strike' : 'roll-box';
        } else {
          r3El.textContent = '-';
          r3El.className = 'roll-box';
        }
      }
    }

    if (totalEl) {
      totalEl.textContent = f.runningTotal !== null ? `${f.runningTotal}` : '-';
    }
  }
}

function updateRadarUI() {
  bowlCtx.pins.forEach((pin) => {
    const dot = document.getElementById(`radar-pin-${pin.id}`);
    if (dot) {
      if (pin.isKnocked || pin.isSwept) {
        dot.className = 'pin-dot knocked';
      } else {
        dot.className = 'pin-dot standing';
      }
    }
  });
}

function updateTelemetryUI(speed: number, vla: number, hla: number) {
  const sEl = document.getElementById('hud-ball-speed');
  const vEl = document.getElementById('hud-vla');
  const hEl = document.getElementById('hud-hla');

  if (sEl) sEl.textContent = `${speed.toFixed(1)} MPH`;
  if (vEl) vEl.textContent = `${vla.toFixed(1)}°`;
  if (hEl) hEl.textContent = `${hla >= 0 ? '+' : ''}${hla.toFixed(1)}°`;
}

let retroTimeout: ReturnType<typeof setTimeout> | null = null;
function triggerRetroOverlay(type: 'strike' | 'spare' | 'gutter' | 'turkey') {
  const overlay = document.getElementById('retro-anim-overlay');
  const icon = document.getElementById('retro-icon');
  const title = document.getElementById('retro-title');
  const sub = document.getElementById('retro-subtitle');

  if (!overlay || !icon || !title || !sub) return;

  switch (type) {
    case 'strike':
      icon.textContent = '💥';
      title.textContent = 'STRIKE!';
      sub.textContent = 'POCKET EXPLOSION!';
      break;
    case 'turkey':
      icon.textContent = '🦃';
      title.textContent = 'TURKEY!';
      sub.textContent = '3 STRIKES IN A ROW!';
      break;
    case 'spare':
      icon.textContent = '✨';
      title.textContent = 'SPARE!';
      sub.textContent = 'CLEAN SWEEP PICKUP!';
      break;
    case 'gutter':
      icon.textContent = '🚨';
      title.textContent = 'GUTTER BALL';
      sub.textContent = 'SLID INTO THE CANAL!';
      break;
  }

  overlay.classList.remove('hidden');

  if (retroTimeout) clearTimeout(retroTimeout);
  retroTimeout = setTimeout(() => {
    overlay.classList.add('hidden');
  }, 1600);
}

let toastTimer: ReturnType<typeof setTimeout> | null = null;
function showToast(title: string, desc: string, scoreText: string) {
  const el = document.getElementById('event-toast');
  const tTitle = document.getElementById('toast-title');
  const tDesc = document.getElementById('toast-desc');
  const tScore = document.getElementById('toast-score');

  if (!el || !tTitle || !tDesc || !tScore) return;

  tTitle.textContent = title;
  tDesc.textContent = desc;
  tScore.textContent = scoreText;
  el.classList.remove('hidden');

  if (toastTimer) clearTimeout(toastTimer);
  toastTimer = setTimeout(() => {
    el.classList.add('hidden');
  }, 1800);
}

function showPinsetterBanner(text: string) {
  const banner = document.getElementById('pinsetter-banner');
  const bText = document.getElementById('pinsetter-text');
  if (banner && bText) {
    bText.textContent = text;
    banner.classList.remove('hidden');
  }
}

function hidePinsetterBanner() {
  const banner = document.getElementById('pinsetter-banner');
  if (banner) banner.classList.add('hidden');
}

function showRecapModal() {
  const modal = document.getElementById('recap-modal');
  if (!modal) return;

  const b = bowlCtx.bowler;
  const scoreVal = document.getElementById('recap-final-score');
  const gradeVal = document.getElementById('recap-grade');
  const strikesVal = document.getElementById('recap-strikes');
  const sparesVal = document.getElementById('recap-spares');
  const guttersVal = document.getElementById('recap-gutters');
  const cleanVal = document.getElementById('recap-clean-frames');

  if (scoreVal) scoreVal.textContent = `${b.totalScore}`;
  if (strikesVal) strikesVal.textContent = `${b.strikesCount}`;
  if (sparesVal) sparesVal.textContent = `${b.sparesCount}`;
  if (guttersVal) guttersVal.textContent = `${b.gutterCount}`;

  // Clean frames count
  let cleanCount = 0;
  b.frames.forEach((f) => {
    if (f.isStrike || f.isSpare) cleanCount++;
  });
  if (cleanVal) cleanVal.textContent = `${cleanCount} / 5`;

  if (gradeVal) {
    if (b.totalScore >= 120) gradeVal.textContent = '🏆 PERFECT STRATEGY MASTER!';
    else if (b.totalScore >= 80) gradeVal.textContent = '⭐ TOUR PRO BOWLER!';
    else if (b.totalScore >= 50) gradeVal.textContent = '🎳 SOLID CLUB PLAY!';
    else gradeVal.textContent = '⚡ WARM-UP ROUND!';
  }

  modal.classList.remove('hidden');
}

// ============================================================================
// Camera Management & Controls
// ============================================================================

function toggleCameraView() {
  if (bowlCtx.viewMode === 'tee') {
    bowlCtx.viewMode = 'drone';
  } else if (bowlCtx.viewMode === 'drone') {
    bowlCtx.viewMode = 'pocket';
  } else {
    bowlCtx.viewMode = 'tee';
  }

  const badge = document.getElementById('cam-badge-text');
  if (badge) {
    badge.textContent = bowlCtx.viewMode === 'tee'
      ? '📷 TEE CAM (C)'
      : bowlCtx.viewMode === 'drone'
      ? '🚁 DECK DRONE CAM (C)'
      : '🎯 POCKET CAM (C)';
  }

  updateCameraPositions();
}

function updateCameraPositions() {
  if (!bowlCtx.camera) return;

  if (bowlCtx.viewMode === 'tee') {
    bowlCtx.camera.setPositions(bowlCtx.startPoint, bowlCtx.aimPoint);
  } else if (bowlCtx.viewMode === 'drone') {
    // Overhead aerial view looking down at pin triangle
    bowlCtx.camera.position.set(0, 14.0, TARGET_DISTANCE_METERS - 8.0);
    bowlCtx.camera.lookAt(0, 0.4, TARGET_DISTANCE_METERS + 1.2);
  } else if (bowlCtx.viewMode === 'pocket') {
    // Low dramatic pocket angle right next to headpin
    bowlCtx.camera.position.set(2.8, 1.2, TARGET_DISTANCE_METERS - 3.5);
    bowlCtx.camera.lookAt(-0.2, 1.0, TARGET_DISTANCE_METERS + 1.0);
  }
}

function nudgeAim(deg: number) {
  if (bowlCtx.golfBall?.isShotActive) return;

  const currentRad = Math.atan2(bowlCtx.aimPoint.x, bowlCtx.aimPoint.z);
  const newRad = THREE.MathUtils.clamp(currentRad + THREE.MathUtils.degToRad(deg), -0.15, 0.15);
  const dist = bowlCtx.aimPoint.length();

  bowlCtx.aimPoint.x = Math.sin(newRad) * dist;
  bowlCtx.aimPoint.z = Math.cos(newRad) * dist;

  if (bowlCtx.camera) {
    bowlCtx.camera.setPositions(bowlCtx.startPoint, bowlCtx.aimPoint);
  }
  if (bowlCtx.golfBall) {
    bowlCtx.golfBall.aimAt(bowlCtx.aimPoint);
  }

  const aimBadge = document.getElementById('aim-badge-text');
  if (aimBadge) {
    const degDisplay = THREE.MathUtils.radToDeg(newRad).toFixed(1);
    aimBadge.textContent = `🎯 AIM: ${degDisplay}° (A/D)`;
  }
}

function setupControls() {
  // Hotkeys
  window.addEventListener('keydown', (e) => {
    if (e.key === '1') {
      // Perfect Pocket Strike (1-3 pocket)
      processShotImpact({ ballSpeed: 88, verticalLaunchAngle: 26, horizontalLaunchAngle: 1.1, spinSpeed: 5200, spinAxis: 0 });
    } else if (e.key === '2') {
      // Split shot (Leaves 7-10)
      processShotImpact({ ballSpeed: 82, verticalLaunchAngle: 28, horizontalLaunchAngle: 0.0, spinSpeed: 4800, spinAxis: 0 });
    } else if (e.key === '3') {
      // Brooklyn Spare (1-2 pocket)
      processShotImpact({ ballSpeed: 84, verticalLaunchAngle: 27, horizontalLaunchAngle: -1.2, spinSpeed: 5000, spinAxis: 0 });
    } else if (e.key === '4') {
      // Gutter Ball
      processShotImpact({ ballSpeed: 75, verticalLaunchAngle: 30, horizontalLaunchAngle: -5.5, spinSpeed: 6000, spinAxis: 0 });
    } else if (e.key === ' ') {
      // Normal pitch shot with current aim
      const aimOffsetDeg = THREE.MathUtils.radToDeg(Math.atan2(bowlCtx.aimPoint.x, bowlCtx.aimPoint.z));
      processShotImpact({
        ballSpeed: 80 + (Math.random() * 8 - 4),
        verticalLaunchAngle: 28 + (Math.random() * 3 - 1.5),
        horizontalLaunchAngle: aimOffsetDeg + (Math.random() * 1.6 - 0.8),
        spinSpeed: 5400,
        spinAxis: 0,
      });
    } else if (e.key === 'c' || e.key === 'C') {
      toggleCameraView();
    } else if (e.key === 'r' || e.key === 'R') {
      initScorecard();
      runPinsetter(true);
    } else if (e.key === 'm' || e.key === 'M') {
      bowlCtx.audioMuted = !bowlCtx.audioMuted;
    } else if (e.key === 'a' || e.key === 'A' || e.key === 'ArrowLeft') {
      nudgeAim(-0.5);
    } else if (e.key === 'd' || e.key === 'D' || e.key === 'ArrowRight') {
      nudgeAim(0.5);
    }
  });

  // Buttons
  document.getElementById('btn-strike')?.addEventListener('click', () => {
    processShotImpact({ ballSpeed: 88, verticalLaunchAngle: 26, horizontalLaunchAngle: 1.1, spinSpeed: 5200, spinAxis: 0 });
  });
  document.getElementById('btn-split')?.addEventListener('click', () => {
    processShotImpact({ ballSpeed: 82, verticalLaunchAngle: 28, horizontalLaunchAngle: 0.0, spinSpeed: 4800, spinAxis: 0 });
  });
  document.getElementById('btn-spare')?.addEventListener('click', () => {
    processShotImpact({ ballSpeed: 84, verticalLaunchAngle: 27, horizontalLaunchAngle: -1.2, spinSpeed: 5000, spinAxis: 0 });
  });
  document.getElementById('btn-gutter')?.addEventListener('click', () => {
    processShotImpact({ ballSpeed: 75, verticalLaunchAngle: 30, horizontalLaunchAngle: -5.5, spinSpeed: 6000, spinAxis: 0 });
  });
  document.getElementById('btn-free-shot')?.addEventListener('click', () => {
    const aimOffsetDeg = THREE.MathUtils.radToDeg(Math.atan2(bowlCtx.aimPoint.x, bowlCtx.aimPoint.z));
    processShotImpact({
      ballSpeed: 80 + (Math.random() * 8 - 4),
      verticalLaunchAngle: 28 + (Math.random() * 3 - 1.5),
      horizontalLaunchAngle: aimOffsetDeg + (Math.random() * 1.6 - 0.8),
      spinSpeed: 5400,
      spinAxis: 0,
    });
  });
  document.getElementById('btn-cam-toggle')?.addEventListener('click', () => {
    toggleCameraView();
  });
  document.getElementById('btn-reset-game')?.addEventListener('click', () => {
    initScorecard();
    runPinsetter(true);
  });
  document.getElementById('btn-audio-toggle')?.addEventListener('click', () => {
    bowlCtx.audioMuted = !bowlCtx.audioMuted;
  });
  document.getElementById('btn-play-again')?.addEventListener('click', () => {
    document.getElementById('recap-modal')?.classList.add('hidden');
    initScorecard();
    runPinsetter(true);
  });
  document.getElementById('btn-exit-hub')?.addEventListener('click', () => {
    if (window.opener || (window as unknown as { arcadeAPI: { returnToMenu: () => void } }).arcadeAPI) {
      (window as unknown as { arcadeAPI: { returnToMenu: () => void } }).arcadeAPI.returnToMenu();
    } else {
      window.location.href = '../../src/menu.html';
    }
  });
}

function onShotEnded() {
  if (bowlCtx.camera && bowlCtx.viewMode === 'tee') {
    bowlCtx.camera.setTracking(false);
    bowlCtx.camera.setPositions(bowlCtx.startPoint, bowlCtx.aimPoint);
  }
  if (bowlCtx.golfBall) {
    bowlCtx.golfBall.reset(bowlCtx.aimPoint, bowlCtx.startPoint);
  }
}

// ============================================================================
// Initialization & World Setup
// ============================================================================

let isBowlingInitialized = false;
let bowlingSetupData: OpenGolfSim.SetupData | undefined;

async function setupWorld() {
  const canvas = document.getElementById('canvas') as HTMLCanvasElement;
  bowlCtx.renderer = new FuseRenderer({
    canvas,
    adaptive: true,
    renderMode: 'webgpu',
    forceWebGL: bowlingSetupData?.backend === 'webgl',
    qualityLevel: bowlingSetupData?.qualityLevel ?? QualityMode.Epic,
  });
  await bowlCtx.renderer.init();
}

async function setupGame() {
  if (isBowlingInitialized) return;
  isBowlingInitialized = true;
  document.body.style.opacity = '1';

  await setupWorld();

  bowlCtx.scene = new THREE.Scene();

  // 1. Particle System
  bowlCtx.particles = new ArcadeParticleSystem(bowlCtx.scene, 800);

  // 2. Playfield & Arena
  createBowlingArena();

  // 3. Directional Key Light
  const dirLight = new THREE.DirectionalLight(0xffffff, 2.8);
  dirLight.position.set(30, 80, -20);
  dirLight.target.position.set(0, 1.2, TARGET_DISTANCE_METERS);
  bowlCtx.scene.add(dirLight);
  bowlCtx.scene.add(dirLight.target);
  bowlCtx.dirLight = dirLight;

  // Pin Deck Overhead Spotlight
  const pinSpot = new THREE.SpotLight(0xffffff, 4.5, 80, Math.PI / 4, 0.4);
  pinSpot.position.set(0, 16, TARGET_DISTANCE_METERS - 4.0);
  pinSpot.target.position.set(0, 1.0, TARGET_DISTANCE_METERS + 1.2);
  bowlCtx.scene.add(pinSpot);
  bowlCtx.scene.add(pinSpot.target);
  bowlCtx.pinSpotLight = pinSpot;

  // Sky / Ground Ambient Fill (deep ultraviolet)
  const hemiLight = new THREE.HemisphereLight(0xa855f7, 0x090614, 2.2);
  bowlCtx.scene.add(hemiLight);

  // 4. Camera (Constructed with ground mesh & tee auto-positioning)
  bowlCtx.camera = new ShotPerspectiveCamera({
    scene: bowlCtx.groundMesh,
    far: 1200,
    fov: 38,
    autoPosition: true,
    cameraOffsetYZ: [2.2, 11],
  });
  bowlCtx.camera.setPositions(bowlCtx.startPoint, bowlCtx.aimPoint);
  bowlCtx.camera.update(0, bowlCtx.startPoint, bowlCtx.aimPoint);

  // 5. Golf Ball with Ground Colliders
  const groundColliders = [bowlCtx.groundMesh!, bowlCtx.laneMesh!].filter(Boolean);
  bowlCtx.golfBall = new GolfBall(bowlCtx.scene, {
    setupData: bowlingSetupData || {},
    groundMeshes: groundColliders,
    waitTime: 800,
    clearTrail: 'start',
    stimpLevel: 11,
  });
  bowlCtx.golfBall.reset(bowlCtx.aimPoint, bowlCtx.startPoint);
  bowlCtx.golfBall.on('shotEnded', onShotEnded);

  // Post-processing pipeline
  if (bowlCtx.renderer) {
    bowlCtx.renderer.setupPostProcessing(bowlCtx.scene, bowlCtx.camera);
    await bowlCtx.renderer.compile(bowlCtx.scene, bowlCtx.camera);
  }

  setupControls();
  initScorecard();
  updateRadarUI();

  // Animation Loop
  animate(0);
  app.setLoaded();
  document.body.style.opacity = '1';
}

// ============================================================================
// Render & Physics Animation Loop
// ============================================================================

function animate(animDelta: number) {
  requestAnimationFrame(animate);
  bowlCtx.timer.update(animDelta);
  const rawDelta = bowlCtx.timer.getDelta();
  const delta = Math.max(0.001, Math.min(rawDelta > 0.0001 ? rawDelta : 0.016, 0.08));

  // 1. Update Physical Pins (Tumbling & Velocity Damping)
  bowlCtx.pins.forEach((pin) => {
    if (pin.isKnocked && !pin.isSwept) {
      // Integrate linear velocity
      pin.pos.x += pin.velocity.x * delta;
      pin.pos.y = Math.max(0.25, pin.pos.y + pin.velocity.y * delta);
      pin.pos.z += pin.velocity.z * delta;

      // Gravity on pin
      if (pin.pos.y > 0.25) {
        pin.velocity.y -= 9.8 * delta;
      } else {
        pin.velocity.y = 0;
        // Friction on floor
        pin.velocity.x *= Math.pow(0.85, delta * 60);
        pin.velocity.z *= Math.pow(0.85, delta * 60);
      }

      // Integrate angular tumble
      pin.rot.x += pin.angularVelocity.x * delta;
      pin.rot.y += pin.angularVelocity.y * delta;
      pin.rot.z += pin.angularVelocity.z * delta;

      // Friction on rotation
      pin.angularVelocity.multiplyScalar(Math.pow(0.88, delta * 60));

      // Domino Pin-to-Pin Cascade Physics
      if (pin.velocity.lengthSq() > 0.16) {
        bowlCtx.pins.forEach((otherPin) => {
          if (!otherPin.isKnocked && !otherPin.isSwept) {
            const dist = pin.pos.distanceTo(otherPin.pos);
            if (dist < PIN_RADIUS * 2.4) {
              otherPin.isKnocked = true;
              otherPin.velocity.copy(pin.velocity).multiplyScalar(0.75);
              otherPin.angularVelocity.set(
                (Math.random() - 0.5) * 7.0,
                (Math.random() - 0.5) * 5.0,
                (Math.random() - 0.5) * 7.0
              );
              playAudio('pin_clatter');
              updateRadarUI();
            }
          }
        });
      }

      pin.meshGroup.position.copy(pin.pos);
      pin.meshGroup.rotation.copy(pin.rot);
    }
  });

  // 2. Update Golf Ball and Camera
  if (bowlCtx.golfBall && bowlCtx.camera) {
    bowlCtx.golfBall.update(delta);

    if (
      bowlCtx.viewMode === 'tee' &&
      bowlCtx.golfBall.isShotActive &&
      bowlCtx.golfBall.object &&
      Number.isFinite(bowlCtx.golfBall.object.position.x) &&
      Number.isFinite(bowlCtx.golfBall.object.position.y) &&
      Number.isFinite(bowlCtx.golfBall.object.position.z)
    ) {
      bowlCtx.camera.track(delta, bowlCtx.startPoint, bowlCtx.golfBall.object.position);
    } else if (bowlCtx.viewMode === 'tee') {
      bowlCtx.camera.update(delta, bowlCtx.startPoint, bowlCtx.aimPoint);
      bowlCtx.golfBall.aimAt(bowlCtx.aimPoint);
    } else {
      updateCameraPositions();
    }
  }

  // 3. Camera Trauma / Recoil Shake
  if (bowlCtx.cameraTrauma > 0 && bowlCtx.camera) {
    const shake = bowlCtx.cameraTrauma * bowlCtx.cameraTrauma;
    bowlCtx.camera.position.x += (Math.random() - 0.5) * 0.35 * shake;
    bowlCtx.camera.position.y += (Math.random() - 0.5) * 0.35 * shake;
    bowlCtx.cameraTrauma = Math.max(0, bowlCtx.cameraTrauma - delta * 2.2);
  }

  // 4. Update Particle Systems
  if (bowlCtx.particles) {
    bowlCtx.particles.update(delta);
  }

  // 5. Render Scene
  if (bowlCtx.renderer && bowlCtx.camera) {
    bowlCtx.renderer.render(bowlCtx.scene, bowlCtx.camera);
  }
}

// ============================================================================
// AppBridge Integration (Launch Monitor Handshake)
// ============================================================================

app.initialize(() => {
  document.body.style.opacity = '1';
  if (app.appType === 'web') {
    setupGame();
  } else {
    setTimeout(() => {
      if (!isBowlingInitialized) {
        setupGame();
      }
    }, 600);
  }
});

app.on('setup', (payload: any) => {
  bowlingSetupData = payload?.setupData;
  setupGame();
});

app.on('shot', (shot: OpenGolfSim.Shot) => {
  processShotImpact(shot);
});
